// Package auth says who a request is and what they may do.
package auth

import "example.com/tally/internal/store"

// Principal is the member a request acts for: the owner of the API key it presented, in that key's organization, with the
// member's current role.
type Principal struct {
	OrgID  string
	UserID string
	KeyID  string
	Role   store.Role
}

// CanWrite reports whether a role may change anything. Viewers only read.
func CanWrite(r store.Role) bool { return r != store.RoleViewer }

// CanManageTeam reports whether a role may manage the organization's settings, members and invites.
func CanManageTeam(r store.Role) bool { return r == store.RoleOwner || r == store.RoleAdmin }
	shutdown, cancel := context.WithTimeout(context.Background(), 10*time.Second)
	defer cancel()
	_ = hs.Shutdown(shutdown)
	runner.Stop()
	if err := snapshot.Save(st, *data, clk.Now()); err != nil {
		log.Error("save snapshot", "err", err)
		os.Exit(1)
	}
}

// seed adds a demo organization with an owner and prints the owner's API key.
func seed(st *store.Store, now time.Time, log *slog.Logger) error {
	o, err := st.CreateOrg("Demo Co", store.OrgTeam, "UTC", 0, now)
	if err != nil {
		return err
	}
	u, err := st.CreateUser("owner@demo.example", "Demo Owner", now)
	if err != nil {
		return err
	}
	if _, err := st.AddMember(o.ID, u.ID, store.RoleOwner, now); err != nil {
		return err
	}
	k, err := st.CreateAPIKey(o.ID, u.ID, "Demo key", now)
	if err != nil {
		return err
	}
	log.Info("demo organization created", "org", o.ID, "api_key", k.Token)
	return nil
}

// NewOrg adds an organization with an owner (owner@<name>.example) and the owner's API key.
func (e *Env) NewOrg(name string, plan store.OrgPlan, timeZone string) Org {
	e.T.Helper()
	now := e.Clock.Now()
	o, err := e.Store.CreateOrg(name, plan, timeZone, 0, now)
	if err != nil {
		e.T.Fatalf("create org %s: %v", name, err)
	}
	u, err := e.Store.CreateUser("owner@"+strings.ToLower(name)+".example", name+" Owner", now)
	if err != nil {
		e.T.Fatalf("create owner of %s: %v", name, err)
	}
	if _, err := e.Store.AddMember(o.ID, u.ID, store.RoleOwner, now); err != nil {
		e.T.Fatal(err)
	}
	k, err := e.Store.CreateAPIKey(o.ID, u.ID, "Owner key", now)
	if err != nil {
		e.T.Fatal(err)
	}
	return Org{Org: o, Owner: u, Key: k.Token}
}

// AddMember adds a new user with this email address to org with a role, and returns them with an API key of theirs.
func (e *Env) AddMember(org Org, email string, role store.Role) (store.User, string) {
	e.T.Helper()
	now := e.Clock.Now()
	u, ok := e.Store.UserByEmail(email)
	if !ok {
		var err error
		if u, err = e.Store.CreateUser(email, strings.Split(email, "@")[0], now); err != nil {
			e.T.Fatal(err)
		}
	}
	if _, err := e.Store.AddMember(org.ID, u.ID, role, now); err != nil {
		e.T.Fatal(err)
	}
	k, err := e.Store.CreateAPIKey(org.ID, u.ID, "Key of "+email, now)
	if err != nil {
		e.T.Fatal(err)
	}
	return u, k.Token
}

// Response is the server's answer.
type Response struct {
	Code   int
	Header http.Header
	Body   []byte
}

// JSON decodes the body into v, failing the test when it cannot.
func (r *Response) JSON(t testing.TB, v any) {
	t.Helper()
	if err := json.Unmarshal(r.Body, v); err != nil {
		t.Fatalf("response %d is not the JSON expected: %v\n%s", r.Code, err, r.Body)
	}
}

// Map decodes the body as a JSON object.
func (r *Response) Map(t testing.TB) map[string]any {

