// lastUsedInterval is the least time between two recorded uses of a key. A busier key is recorded at most this often.
const lastUsedInterval = time.Minute

// TouchAPIKey records that a key was used. It leaves LastUsedAt alone if the key was last recorded less than a minute ago.
func (s *Store) TouchAPIKey(id string, now time.Time) {
	s.mu.Lock()
	defer s.mu.Unlock()
	if k, ok := s.apiKeys[id]; ok {
		if k.LastUsedAt != nil && now.Sub(*k.LastUsedAt) < lastUsedInterval {
			return
		}
		t := now.UTC()
		k.LastUsedAt = &t
		s.apiKeys[id] = k
	}
}

