func TestAPIKeyTokenFormat(t *testing.T) {
	const alphabet = "ABCDEFGHIJKLMNOPQRSTUVWXYZabcdefghijklmnopqrstuvwxyz0123456789"
	seen := map[string]bool{}
	counts := map[rune]int{}
	for i := 0; i < 500; i++ {
		tok := newAPIKeyToken()
		if len(tok) != len("tly_")+40 || tok[:4] != "tly_" {
			t.Fatalf("token %q has the wrong shape", tok)
		}
		for _, c := range tok[4:] {
			if !strings.ContainsRune(alphabet, c) {
				t.Fatalf("token %q has the character %q", tok, c)
			}
			counts[c]++
		}
		if seen[tok] {
			t.Fatalf("token %q repeated", tok)
		}
		seen[tok] = true
	}
	// 500 tokens of 40 characters is 20000 draws over 62 characters: about 323 each. A broken generator would be far off.
	for _, c := range alphabet {
		if counts[c] < 150 || counts[c] > 500 {
			t.Fatalf("character %q appears %d times in 20000", c, counts[c])
		}
	}
}

func TestAPIKeyStoresOnlyHash(t *testing.T) {
	s := New()
	o := newOrg(t, s, "Acme")
	u, _ := s.CreateUser("ann@example.com", "Ann", t0)
	_, _ = s.AddMember(o.ID, u.ID, RoleMember, t0)
	k, err := s.CreateAPIKey(o.ID, u.ID, "k", t0)
	if err != nil {
		t.Fatal(err)
	}
	sum := sha256.Sum256([]byte(k.Token))
	if k.TokenHash != hex.EncodeToString(sum[:]) || k.Last4 != k.Token[len(k.Token)-4:] {
		t.Fatalf("returned key = %+v", k)
	}
	stored, ok := s.APIKey(o.ID, k.ID)
	if !ok || stored.Token != "" || stored.TokenHash != k.TokenHash || stored.Last4 != k.Last4 {
		t.Fatalf("stored key = %+v", stored)
	}
	for _, listed := range s.APIKeys(o.ID) {
		if listed.Token != "" {
			t.Fatalf("listed key carries a token: %+v", listed)
		}
	}
	if got, ok := s.APIKeyByToken(k.Token); !ok || got.Token != "" {
		t.Fatalf("APIKeyByToken = %+v %v", got, ok)
	}
	if _, ok := s.APIKeyByToken(k.TokenHash); ok {
		t.Fatal("the stored hash works as a token")
	}
	for _, st := range []State{s.Export()} {
		if strings.Contains(fmt.Sprintf("%+v", st.APIKeys), k.Token) {
			t.Fatal("the export holds the token")
		}
	}
}

func TestTouchAPIKeyWritesAtMostOncePerMinute(t *testing.T) {
	s := New()
	o := newOrg(t, s, "Acme")
	u, _ := s.CreateUser("ann@example.com", "Ann", t0)
	_, _ = s.AddMember(o.ID, u.ID, RoleMember, t0)
	k, _ := s.CreateAPIKey(o.ID, u.ID, "k", t0)
	last := func() time.Time {
		t.Helper()
		got, _ := s.APIKey(o.ID, k.ID)
		if got.LastUsedAt == nil {
			t.Fatal("no last use recorded")
		}
		return *got.LastUsedAt
	}

	s.TouchAPIKey(k.ID, t0)
	if !last().Equal(t0) {
		t.Fatalf("first use = %v", last())
	}
	s.TouchAPIKey(k.ID, t0.Add(59*time.Second))
	if !last().Equal(t0) {
		t.Fatalf("a use 59s later was recorded: %v", last())
	}
	s.TouchAPIKey(k.ID, t0.Add(60*time.Second))
	if !last().Equal(t0.Add(60 * time.Second)) {
		t.Fatalf("a use 60s later was not recorded: %v", last())
	}
	s.TouchAPIKey(k.ID, t0.Add(100*time.Second))
	if !last().Equal(t0.Add(60 * time.Second)) {
		t.Fatalf("a use 40s after the last record was recorded: %v", last())
	}
}

